// src/generators/npc/generatedNpcTitle.js
function resolveGeneratedNpcTitle({
  role,
  culturalTitle,
  category,
  worldLaw
}) {
  return worldLaw.allowsRole({
    role,
    title: culturalTitle,
    category,
    source: "generated"
  }) ? culturalTitle : role;
}

