// src/generators/narrativeProse.js
var sentenceCase = (value) => {
  const text8 = String(value || "");
  return text8 ? text8[0].toUpperCase() + text8.slice(1) : text8;
};
var opensSentence = (text8, offset) => /(?:^|[.!?]\s+)$/.test(String(text8).slice(0, offset));
var fillSentenceSlots = (template, values, fallbacks = {}) => String(template).replace(
  /\{(\w+)\}/g,
  (whole, key, offset, text8) => {
    const value = values[key] || fallbacks[key];
    if (!value) return whole;
    return opensSentence(text8, offset) ? sentenceCase(value) : String(value);
  }
);
var collapseArticleSeams = (value) => String(value || "").replace(
  /\b([Tt]he)\s+(?:[Tt]he|[Aa]|[Aa]n)\s+/g,
  (_match, leadingArticle) => `${leadingArticle} `
);

