  factions.forEach((faction) => {
    faction.power = totalPower > 0 ? Math.round((faction.power || 0) / totalPower * 100) : 0;
  });
  factions.sort((a, b) => a.isGoverning ? -1 : b.isGoverning ? 1 : b.power - a.power);
  annotateFactionStanding(factions, force);
  return factions;
