// src/generators/institutionProbability.js
var getPriorityModifiers = (tier, goodsToggles = {}) => {
  const tierGoods = GOODS_MODIFIERS_BY_TIER[tier] || {};
  const penalties = {};
  Object.entries(tierGoods).forEach(([goodName, good]) => {
    if (goodsToggles[`${tier}_good_${goodName}`] === false && good.institutionKeywords) {
      good.institutionKeywords.forEach((keyword) => {
        penalties[keyword] = (penalties[keyword] || 1) * 0.35;
      });
    }
  });
  return penalties;
};
var getBaseChance = (baseChance, category, name, config, neighbor, goodsToggles = {}) => {
  const cat = category.toLowerCase();
  const inst = name.toLowerCase();
  let chance2 = baseChance;
  const declaredLicence = institutionCatalogMagicLicence(name);
  const licensedForMagic = magicLicenceAtLeast(declaredLicence, "low");
  const resolvedTier = config.tier || (TIER_ORDER.includes(config.settType) ? config.settType : null);
  if (cat.includes("economy") || inst.includes("market") || inst.includes("guild") || inst.includes("merchant") || inst.includes("bank")) {
    chance2 *= config.priorityEconomy / 50;
  }
  if (cat.includes("government")) {
    if (inst.includes("lord's") || inst.includes("noble") || inst.includes("royal seat")) {
      const milMult = config.priorityMilitary / 50;
      const econMod = Math.max(0.4, 1 - (config.priorityEconomy - 50) / 150);
      chance2 *= milMult * econMod;
    } else if (inst.includes("guild") || inst.includes("merchant oligarchy") || inst.includes("mayor and council")) {
      const econMult = config.priorityEconomy / 50;
      const milMod = Math.max(0.4, 1 - (config.priorityMilitary - 50) / 150);
      chance2 *= econMult * milMod;
    } else if (inst.includes("cathedral") || inst.includes("prelate")) {
      chance2 *= config.priorityReligion / 50;
    } else if (inst.includes("democratic") || inst.includes("city-state")) {
      chance2 *= Math.max(0.5, config.priorityEconomy / 70);
    }
  }
  if (cat.includes("defense") || cat.includes("military") || inst.includes("wall") || inst.includes("garrison") || inst.includes("watch") || inst.includes("guard") || inst.includes("fortif") || inst.includes("citadel") || inst.includes("barracks") || inst.includes("armory")) {
    chance2 *= config.priorityMilitary / 50;
  }
  const magicPriorityScaled = declaredLicence !== null ? licensedForMagic : cat.includes("magic") || // @non-catalog-fallback MF-CH2
  inst.includes("wizard") || inst.includes("mage") || inst.includes("alchemist") || inst.includes("enchant") || inst.includes("spell") || inst.includes("arcane") || inst.includes("teleportation") || inst.includes("planar");
  if (magicPriorityScaled) {
    const magicMult = config.priorityMagic / 50;
    const tierMagicPenalty = {
      thorp: 0.15,
      hamlet: 0.25,
      village: 0.4,
      town: 0.75,
      city: 1,
      metropolis: 1
    }[resolvedTier || "town"] ?? 0.75;
    chance2 *= magicMult * tierMagicPenalty;
    const isDruidInst = inst.includes("druid") || inst.includes("grove shrine") || inst.includes("sacred grove") || // J33: Warden's Lodge is defence, not druid (the owner, 2026-10-01)
    inst.includes("elder grove");
    if (isDruidInst) {
      const route = config.tradeRouteAccess || "road";
      const hasMagicalNode = nativeSemanticResourceKeys(config).includes("magical_node");
      const routeBoost = { isolated: 1.8, road: 1.4, river: 1.5, crossroads: 0.9, port: 0.8 }[route] ?? 1;
      const nodeBoost = hasMagicalNode ? 1.5 : 1;
      chance2 *= routeBoost * nodeBoost;
    }
  }
  if (cat.includes("religious") || inst.includes("church") || inst.includes("cathedral") || inst.includes("monastery") || inst.includes("temple") || inst.includes("priest") || inst.includes("shrine") || inst.includes("abbey") || inst.includes("friary") || inst.includes("hospital")) {
    chance2 *= config.priorityReligion / 50;
  }
  if (cat.includes("criminal") || inst.includes("thieves") || inst.includes("assassin") || inst.includes("smuggl") || inst.includes("black market") || inst.includes("fence") || inst.includes("underground") || inst.includes("criminal") || inst.includes("outlaw") || inst.includes("bandit")) {
    chance2 *= config.priorityCriminal / 50;
  }
  if ((config.tradeRouteAccess === "port" || config.tradeRouteAccess === "crossroads") && (inst.includes("market") || inst.includes("merchant") || inst.includes("warehouse") || inst.includes("dock") || inst.includes("customs"))) {
    chance2 *= 1.5;
  }
  if (config.tradeRouteAccess === "isolated" && (inst.includes("market") || inst.includes("merchant") || inst.includes("international") || inst.includes("bank"))) {
    chance2 *= 0.3;
  }
  const isHighMagicIsolated = config.tradeRouteAccess === "isolated" && (config.priorityMagic || 0) >= 70 && ["town", "city", "metropolis"].includes(resolvedTier || "");
  if (isHighMagicIsolated && (inst.includes("teleportation") || inst.includes("planar") || inst.includes("airship"))) {
    chance2 = Math.min(1, chance2 * 4);
  }
  if (config.tradeRouteAccess === "port" && (inst.includes("dock") || inst.includes("port") || inst.includes("ship") || inst.includes("warehouse") || inst.includes("navy"))) {
    chance2 *= 2;
  }
  if (config.tradeRouteAccess !== "port" && (inst === "major port" || inst === "navy (if coastal)")) {
    chance2 *= 0;
  }
  if (config.tradeRouteAccess !== "port" && config.tradeRouteAccess !== "river" && inst === "docks/port facilities") {
    chance2 *= 0;
  }
  const magPriority = config.priorityMagic ?? 50;
  const hiMagicInsts = [
    "airship",
    "golem",
    "undead labor",
    "dream parlor",
    "message network",
    "planar",
    "teleportation",
    "high magic"
  ];
  if (magPriority < 66 && hiMagicInsts.some((kw) => inst.includes(kw))) {
    chance2 *= 0;
  }
  const isMagicOrExoticCategory = declaredLicence !== null ? licensedForMagic : cat.includes("magic") || cat === "exotic";
  if (magPriority >= 66 && isMagicOrExoticCategory) {
    chance2 *= 1.8;
  } else if (magPriority <= 25 && isMagicOrExoticCategory) {
    chance2 *= 0.3;
  }
  if (inst.includes("adventurers' charter hall")) {
    chance2 *= config.monsterThreat === "plagued" ? 5 : config.monsterThreat === "frontier" ? 3 : 0.3;
  }
  if (config.monsterThreat === "plagued") {
    if (cat.includes("defense") || inst.includes("wall") || inst.includes("garrison") || inst.includes("barracks") || inst.includes("citadel")) {
      chance2 *= 2;
    }
    if (inst.includes("adventurer") || inst.includes("hireling")) {
      chance2 *= 1.5;
    }
  } else if (config.monsterThreat === "frontier") {
    if (cat.includes("defense") || inst.includes("wall") || inst.includes("garrison")) {
      chance2 *= 1.35;
    }
  } else if (config.monsterThreat === "heartland") {
    if (cat.includes("defense")) {
      chance2 *= 0.5;
    }
  }
  if (neighbor) {
    const profile3 = neighbor.dynamics ? neighbor : null;
    if (profile3) {
      const dyn = profile3.dynamics || {};
      const ownTier = resolvedTier || "village";
      const tierDiff = TIER_ORDER.indexOf(ownTier) - TIER_ORDER.indexOf(profile3.tier || "village");
      if (tierDiff < -1 && (cat.includes("government") || inst.includes("court") || inst.includes("mint"))) {
        chance2 *= 0.4;
      }
      if (cat.includes("defense") || cat.includes("military") || inst.includes("garrison") || inst.includes("barracks") || inst.includes("fortif") || inst.includes("guard")) {
        chance2 *= (1 + (dyn.militaryBias || 0)) * (0.7 + (profile3.militaryStrength || 0.5) * 0.6);
      }
      if (cat.includes("economy") || inst.includes("market") || inst.includes("guild") || inst.includes("merchant")) {
        chance2 *= (ECONOMY_MODE_MARKET_MULT[dyn.economyMode] ?? 1) * (0.8 + (profile3.economicStrength || 0.5) * 0.4);
      }
    } else {
      const neighborTier = neighbor.tier || "village";
      const ownTier = resolvedTier || "village";
      const tierDiff = TIER_ORDER.indexOf(ownTier) - TIER_ORDER.indexOf(neighborTier);
      const relType = (neighbor?.relationshipType || neighbor?.neighborRelationship?.relationshipType || "").toLowerCase();
      if (tierDiff < -1 && (cat.includes("government") || inst.includes("court"))) chance2 *= 0.4;
      if (Math.abs(tierDiff) <= 1 && cat.includes("defense")) chance2 *= 1.5;
      if ((relType.includes("hostile") || relType.includes("rival") || relType.includes("cold_war")) && (cat.includes("defense") || cat.includes("military"))) chance2 *= 1.4;
    }
  }
  const modifiers = getPriorityModifiers(
    resolvedTier || "town",
    goodsToggles
  );
  Object.entries(modifiers).forEach(([keyword, multiplier]) => {
    if (inst.includes(keyword)) chance2 *= multiplier;
  });
  chance2 *= cultureInstitutionMultiplier(config.culture, category, name);
  if (config.magicExists === false && isArcaneInstitution(name, category)) {
    return 0;
  }
  return Math.min(Math.max(chance2, 0), 1);
};

