function normalizedName2(value) {
  return String(value || "").trim().toLowerCase();
}
function institutionLadderEvicts(greaterName, lesserName) {
  const greater = String(greaterName || "");
  const lesser = String(lesserName || "");
  if (!greater || !lesser) return false;
  if (UPGRADE_CHAINS.some(([candidateLesser, candidateGreater]) => candidateGreater === greater && candidateLesser === lesser)) {
    return true;
  }
  const normalizedGreater = normalizedName2(greater);
  const normalizedLesser = normalizedName2(lesser);
  return SUBSUMPTION_RULES.some((rule) => normalizedGreater.includes(normalizedName2(rule.greater)) && rule.lesser.some((candidate) => normalizedName2(candidate) === normalizedLesser));
}
function institutionWouldBeImmediatelyEvicted(rosterNames, candidateName) {
  return (Array.isArray(rosterNames) ? rosterNames : []).some((greaterName) => institutionLadderEvicts(greaterName, candidateName));
}

