  effectiveConfig.stressType = stressTypes[0] || effectiveConfig.stressType || null;
  effectiveConfig.stressTypes = stressTypes.length ? stressTypes : effectiveConfig.stressType ? [effectiveConfig.stressType] : effectiveConfig.stressTypes || [];
