registerStep("generatePopulation", {
  deps: ["coherenceRepairPass", "powerEconomyReconcilePass"],
  reads: ["culture", "economicState", "effectiveConfig", "generationContext", "institutions", "powerStructure", "tier"],
  // ctx keys this step consumes that another step produces (A+ generators.3 data-flow contract); `population` left with the retired mass seam (the people car)
  readsVersion: { economicState: "reconciled" },
  provides: ["npcs", "relationships"],
  phase: "population"
}, (ctx, rng) => {
  const pins = ctx.__pins || null;
  const npcs = drawPopulation(ctx, rng, pins);
  return derivePopulation(ctx, rng, pins, npcs);
});

